CREATE TABLE IF NOT EXISTS hhba_library_semiconductor_recruitment_candidates (
 id TEXT PRIMARY KEY,
 collection_sequence INTEGER NOT NULL UNIQUE CHECK(collection_sequence BETWEEN 1 AND 100),
 employer_display_name TEXT NOT NULL,
 candidate_url TEXT NOT NULL UNIQUE,
 section_id TEXT NOT NULL REFERENCES hhba_library_hall_sections(section_id),
 hall_id TEXT NOT NULL DEFAULT 'semiconductors' CHECK(hall_id='semiconductors'),
 batch_id TEXT NOT NULL DEFAULT 'SEMICONDUCTOR_001_100',
 source_status TEXT NOT NULL DEFAULT 'UNVERIFIED' CHECK(source_status IN ('UNVERIFIED','REVIEWED','REJECTED')),
 collected_at TEXT NOT NULL DEFAULT '2026-11-11'
);
CREATE INDEX IF NOT EXISTS idx_semi_recruitment_section ON hhba_library_semiconductor_recruitment_candidates(section_id,source_status);
